fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    // The problem statement assumes `a` is non-empty, but we handle empty input gracefully.
    a.into_iter()
        .map(|s| {
            let mut parts: Vec<String> = Vec::new();

            // Split on '\n'. If keepends is true, re-attach '\n' to every segment except possibly
            // the last (which only gets it if the original string ended with '\n').
            let mut iter = s.split('\n').peekable();
            while let Some(seg) = iter.next() {
                let is_last = iter.peek().is_none();

                if keepends {
                    if !is_last {
                        parts.push(format!("{seg}\n"));
                    } else {
                        // Last segment: keep as-is (it already represents content after final '\n',
                        // or empty if the string ended with '\n').
                        parts.push(seg.to_string());
                    }
                } else {
                    parts.push(seg.to_string());
                }
            }

            // Ensure the inner vector is non-empty even if the string was empty.
            if parts.is_empty() {
                parts.push(String::new());
            }

            parts
        })
        .collect()
}